/* Testnet session hand-off and this installation's unverified public board.
 * No keys are read. A refresh is a read; every wallet submission needs its own click.
 */
(() => {
  'use strict';
  const C=()=>globalThis.NodusTradeCore,S=()=>globalThis.NodusTradeSession,W=()=>globalThis.NodusTradeWallet;
  const T=(key,params)=>globalThis.NodusTradeText(key,params);
  const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const button=(label,action,disabled=false)=>`<button type="button" class="button" data-live-action="${esc(action)}"${disabled?' disabled':''}>${esc(T(label))}</button>`;
  const field=(id,label,value,type='text')=>`<label class="trade-field" for="${id}"><span>${esc(T(label))}</span><input id="${id}" value="${esc(value)}" type="${type}" autocomplete="off" spellcheck="false" maxlength="160"></label>`;
  const tokenPattern=/^0x[0-9a-f]{64}$/;
  let target=null,context=null,mode='',generation=0,busy=false,message='',session=null,observations=null,pending=null,inspection=null;
  let addresses={nodus:'',bsc:''},secretInput='',board=null,boardMessage='',boardBusy=false,boardGeneration=0;
  let reserveAddresses={nodus:'',bsc:''};
  const capabilities=new Map(),controllers=new Set();
  let csrfToken='',currentOfferId=null,operationVersion=0,boardOperationVersion=0,expiryTimer=null;
  const now=()=>Math.floor(Date.now()/1000);
  function invalidate(){++generation;if(expiryTimer!==null)clearTimeout(expiryTimer);expiryTimer=null;for(const controller of controllers)controller.abort();controllers.clear();observations=null;inspection=null;pending=null;}
  function statusError(e){return T(e?.message&&e.message!==e.code?e.message:e?.code||'The operation failed.');}
  function capture(){if(!target)return;for(const chain of ['nodus','bsc']){const input=target.querySelector('#trade-contract-'+chain);if(input)addresses[chain]=input.value.trim();const own=target.querySelector('#trade-reserve-'+chain);if(own)reserveAddresses[chain]=own.value.trim();}const input=target.querySelector('#trade-claim-secret');if(input)secretInput=input.value.trim();}
  function download(filename,body){let url;try{url=URL.createObjectURL(new Blob([body],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=filename;document.body.appendChild(a);a.click();a.remove();return true;}finally{if(url)URL.revokeObjectURL(url);}}
  async function json(url,options={}){if(options.method==='POST'&&!csrfToken)await json('/api/trade/board');const controller=new AbortController();if(options.method!=='POST')controllers.add(controller);const timer=setTimeout(()=>controller.abort(),12000);try{const response=await fetch(url,{...options,signal:controller.signal,headers:{'Content-Type':'application/json',...(options.method==='POST'?{'X-CSRF-Token':csrfToken}:{}),...options.headers}});const data=await response.json();if(typeof data.csrfToken==='string')csrfToken=data.csrfToken;if(!response.ok)throw Object.assign(new Error(typeof data.error==='string'?data.error:data.error?.message||'The operation failed.'),{code:data.code||data.error?.code});return data;}finally{clearTimeout(timer);controllers.delete(controller);}}
  function sessionForOffer(){if(!context?.offer)throw Error('Choose an offer to continue.');if(!S())throw Error('Network session support is unavailable.');const candidate=S().createSession(context.offer,{...addresses});if(!session||JSON.stringify(session.contracts)!==JSON.stringify(candidate.contracts)||C().exportOffer(session.offer)!==C().exportOffer(candidate.offer))session=candidate;return session;}
  function observationHTML(){if(!observations)return `<p>${T('No live checks yet. Simulation results and saved files are never network verification.')}</p>`;
    return `<div class="trade-legs">${['nodus','bsc'].map(chain=>{const row=inspection?.legs?.[chain],read=observations[chain];return `<section class="trade-leg"><h3>${chain==='nodus'?'NODUS':'TEST-USDT · BSC 97'}</h3><strong>${T(row?.valid?'Network checks passed':'Not verified')}</strong><p>${esc(T(read?.blocker||read?.error?.code||row?.errors?.join(', ')||'Read the current chain state.'))}</p><dl class="trade-meta"><dt>${T('Observed state')}</dt><dd>${esc(T(row?.status||read?.status||'Unknown'))}</dd><dt>${T('Block')}</dt><dd>${esc(read?.height??read?.blockHeight??read?.blockNumber??'—')}</dd></dl></section>`;}).join('')}</div><p>${T('These are observations from configured servers, not independent chain proofs.')}</p><p>${T('Trade stage')}: <strong>${esc(T(inspection?.stage||'unverified'))}</strong></p>`;
  }
  function previewHTML(){if(!pending)return '';const request=pending.request||pending;const summary={chain:request.chain,action:request.action,from:request.from,to:request.to||'CONTRACT CREATION',valueWei:request.valueWei,summary:request.summary};return `<section class="trade-request-preview" id="trade-request-preview"><h3>${T('Review the wallet request')}</h3><pre>${esc(JSON.stringify(summary,null,2))}</pre>${request.containsSecret?`<p class="trade-secret-note">${T('This claim request contains the private secret. Sharing its file reveals it. Check both locks and remaining time first.')}</p><p class="trade-secret-note">${T('Sending this request to a wallet may reveal the secret to its RPC provider before broadcast. Cancelling the wallet prompt does not restore secrecy.')}</p>`:''}<div class="trade-buttons">${button(request.containsSecret?'Export private claim request':'Export unsigned request','request-export',busy)}${request.chain==='bsc'?button(request.containsSecret?'Reveal secret and request wallet approval':'Send with BSC wallet','send',busy):''}${button('Discard request','discard',busy)}</div><p>${T(request.chain==='nodus'?'The current Nodus wallet cannot import this request. The file is a developer hand-off, not a payment.':'Submitting opens the wallet for your approval. A submitted hash does not mean the transaction has confirmed.')}</p></section>`;}
  function renderNetwork(){if(!target||mode!=='network')return;const o=context.offer,w=W()?.getState?.()||{};
    target.innerHTML=`<div class="trade-live"><h2>${T('Network trade · testnets')}</h2><p>${T('Prepare a public trade session, inspect actual chain state, and review wallet requests. Network actions are separate from the simulator.')}</p><div class="notice amber trade-notice">${T('Nodus code verification and wallet hand-off may be unavailable on this installation. Funding and secret-revealing claims stay blocked until the required checks pass.')}</div><p class="trade-live-message" role="status">${esc(message)}</p><div class="trade-buttons">${button('Connect BSC wallet','connect',busy)}<span class="trade-badge">${esc(w.connected?w.address:T('Wallet not connected'))}</span></div><details class="trade-network-tools"><summary>${T('BSC testnet setup')}</summary><p>${T('Deploy a free TEST-USDT token, then a swap bound to that token. Each deployment is a separate wallet transaction. Copy confirmed contract addresses into the fields below.')}</p><div class="trade-buttons">${button('Prepare test token deployment','deploy-mock',busy||!w.connected)}${button('Prepare swap deployment','deploy-swap',busy||!o||!w.connected)}${button('Prepare test token faucet','faucet',busy||!o||!w.connected)}</div></details>${o?`<div class="trade-form">${field('trade-contract-nodus','Published Nodus swap address',addresses.nodus)}${field('trade-contract-bsc','Published BSC token swap address',addresses.bsc)}<p class="trade-wide">${T('TEST-USDT token')}: <code>${esc(o.asset.token)}</code></p></div><div class="trade-buttons">${button('Prepare session','session',busy)}${button('Refresh both networks','refresh',busy)}${button('Export public session','session-export',busy||!session)}<label class="button trade-file">${T('Import public session')}<input id="trade-session-import" type="file" accept=".json,application/json"></label></div><div id="trade-live-observations">${observationHTML()}</div><div class="trade-form"><div class="trade-wide">${field('trade-claim-secret','Claim secret (private, optional)',secretInput,'password')}</div><p class="trade-wide">${T('The maker can use the private recovery file already loaded above. A taker can enter a revealed preimage. Secrets are never sent to the observation service or stored in browser storage.')}</p></div><div class="trade-legs">${['nodus','bsc'].map(chain=>`<section class="trade-leg"><h3>${chain==='nodus'?'NODUS':'TEST-USDT · BSC 97'}</h3><div class="trade-buttons">${chain==='bsc'?button('Prepare exact token approval','prepare:bsc:approve',busy||!inspection?.legs?.bsc?.valid):''}${button('Prepare lock','prepare:'+chain+':open',busy||!inspection?.valid)}${button('Prepare claim','prepare:'+chain+':claim',busy||!inspection?.valid)}${button('Prepare refund','prepare:'+chain+':refund',busy||!inspection?.legs?.[chain]?.valid)}</div></section>`).join('')}</div>`:`<p>${T('Choose an offer to continue.')}</p>`}${previewHTML()}<p>${T('Every refund needs a signed transaction after its deadline. Keep the recovery file and public session independently of this server.')}</p></div>`;
    bindNetwork();
  }
  async function networkAction(action){if(busy)return;capture();busy=true;const serial=generation,operation=++operationVersion;try{
    if(action==='connect'){if(!W())throw Error('BSC wallet support is unavailable.');await W().connect();if(serial!==generation)return;message=T('Wallet connected. Verify the account and BSC testnet (97).');}
    else if(action==='session'){sessionForOffer();observations=null;inspection=null;pending=null;message=T('Public session prepared. No transaction was sent.');}
    else if(action==='session-export'){download('nodus-trade-session.json',S().exportSession(session));message=T('Download created.');}
    else if(action==='refresh'){
      sessionForOffer();pending=null;observations=null;inspection=null;
      const offer=session.offer,legs=C().legs(offer);const results=await Promise.all(['nodus','bsc'].map(async chain=>{const leg=legs.find(item=>item.chain===chain);const params=new URLSearchParams({chain,contract:session.contracts[chain],funder:leg.from,trade_id:offer.id,...(chain==='bsc'?{token:offer.asset.token}:{})});try{return [chain,await json('/api/trade/observe?'+params)];}catch(e){if(e.name==='AbortError')throw e;return [chain,{confirmed:false,runtimeVerified:false,status:'unknown',blocker:e.code||e.message}];}}));
      if(serial!==generation)return;observations=Object.fromEntries(results);inspection=S().inspect(session,observations,now());const checked=Object.values(observations).map(x=>x.checkedAt).filter(Number.isSafeInteger);const expires=checked.length?Math.min(...checked)+S().FRESH_SECONDS:now()+S().FRESH_SECONDS;expiryTimer=setTimeout(()=>{if(serial!==generation||mode!=='network')return;capture();invalidate();message=T('Network checks expired. Refresh both networks.');renderNetwork();},Math.max(0,expires-now())*1000);message=T('Network answers loaded. Review verification results before preparing a transaction.');
    }else if(action.startsWith('prepare:')){
      if(!session||!observations)throw Error('Refresh both networks first.');const [,chain,kind]=action.split(':');const request=await S().request(session,chain,kind,observations,{secret:secretInput||context.secret?.(),now:now()});if(serial!==generation)return;pending=request;message=T('Unsigned request prepared. Review it before export or wallet submission.');
    }else if(action==='deploy-mock'||action==='deploy-swap'){const request=await W().prepareDeployment(action==='deploy-mock'?'mockUsdt':'bsc',action==='deploy-swap'?{token:context.offer.asset.token}:{});if(serial!==generation)return;pending=request;message=T('Deployment request prepared. Nothing has been sent.');}
    else if(action==='faucet'){const request=await W().prepareFaucet(context.offer.asset.token);if(serial!==generation)return;pending=request;message=T('Test token request prepared. These tokens have no monetary value.');}
    else if(action==='request-export'){const request=pending.request||pending;download(request.containsSecret?'PRIVATE-nodus-trade-claim-request.json':'nodus-trade-unsigned-request.json',JSON.stringify(request,null,2)+'\n');message=T('Download created.');}
    else if(action==='discard'){pending=null;message='';}
    else if(action==='send'){
      const request=pending.request||pending;pending=null;const result=await W().submit(request);if(serial!==generation)return;if(session&&['approve','open','claim','refund'].includes(result.action))session=S().recordTransaction(session,{chain:'bsc',action:result.action,hash:result.hash,submittedAt:result.submittedAt});pending=null;observations=null;inspection=null;secretInput='';message=T('Submitted, awaiting network verification: {hash}',{hash:result.hash});
    }
  }catch(e){if(serial===generation&&e.name!=='AbortError')message=statusError(e);}finally{if(operation===operationVersion){busy=false;if(target&&mode==='network')renderNetwork();}}}
  function bindNetwork(){target.querySelectorAll('[data-live-action]').forEach(el=>el.onclick=()=>networkAction(el.dataset.liveAction));for(const chain of ['nodus','bsc']){const input=target.querySelector('#trade-contract-'+chain);if(input)input.oninput=()=>{capture();invalidate();session=null;const view=target.querySelector('#trade-live-observations');if(view)view.innerHTML=observationHTML();target.querySelector('#trade-request-preview')?.remove();target.querySelectorAll('[data-live-action]').forEach(el=>{if(el.dataset.liveAction.startsWith('prepare:')||el.dataset.liveAction==='session-export')el.disabled=true;});};}
    const upload=target.querySelector('#trade-session-import');if(upload)upload.onchange=async event=>{const file=event.target.files?.[0];if(!file)return;const serial=generation;try{if(file.size>65536)throw Error('The file is too large.');const imported=S().importSession(await file.text());if(serial!==generation)return;if(C().exportOffer(imported.offer)!==C().exportOffer(context.offer))throw Error('Import the matching public offer first.');invalidate();session=imported;addresses={...session.contracts};message=T('Public session imported. Refresh both networks; imported files do not verify funding.');}catch(e){message=statusError(e);}renderNetwork();};
  }
  function randomId(){const bytes=crypto.getRandomValues(new Uint8Array(32));return '0x'+Array.from(bytes,b=>b.toString(16).padStart(2,'0')).join('');}
  function validateListing(value){
    if(!value||value.schema!=='nodus-trade/listing-v1'||!tokenPattern.test(value.id)||/^0x0+$/.test(value.id)||typeof value.name!=='string'||!value.name||value.name.length>80||!['sell_nodus','buy_nodus'].includes(value.side))throw Error('Invalid board response.');
    C().amount(value.nodusAmount,'nodus');C().amount(value.usdtAmount,'bsc');
    for(const chain of ['nodus','bsc'])C().address(value.maker?.[chain],chain,'maker');
    const a=value.asset;if(!a||a.kind!=='bep20'||a.chainId!==97||a.decimals!==18||a.symbol!=='TEST-USDT')throw Error('Invalid board response.');C().address(a.token,'bsc','asset');
    for(const key of ['createdAt','expiresAt'])if(!Number.isSafeInteger(value[key])||value[key]<0||value[key]>253402300799)throw Error('Invalid board response.');
    if(value.reservation){const r=value.reservation;if(!Number.isSafeInteger(r.expiresAt)||r.expiresAt<0||r.expiresAt>253402300799)throw Error('Invalid board response.');for(const chain of ['nodus','bsc'])C().address(r.taker?.[chain],chain,'taker');}
    return C().copy(value);
  }
  function listingFields(listing,taker){return {name:listing.name,side:listing.side,nodusAmount:listing.nodusAmount,usdtAmount:listing.usdtAmount,maker:C().copy(listing.maker),taker:C().copy(taker),token:listing.asset.token};}
  function renderBoard(){if(!target||mode!=='board')return;target.innerHTML=`<div class="trade-board"><h2>${T('Shared offers · this installation')}</h2><p>${T('These public advertisements are unsigned and unverified. A reservation does not lock coins or prove control of a wallet.')}</p><p class="trade-live-message" role="status">${esc(boardMessage)}</p><div class="trade-buttons">${button('Refresh shared offers','board-refresh',boardBusy)}${button('Publish advertisement','board-publish',boardBusy)}<label class="button trade-file">${T('Import advertisement management file')}<input id="trade-board-management-import" type="file" accept=".json,application/json"></label></div><p>${T('Publishing uses the selected offer, or the new-offer form. The secret, hashlock and proposed taker are not published. Advertisements are visible only to users of this Observatory server.')}</p><div class="trade-form">${field('trade-reserve-nodus','My Nodus EVM address',reserveAddresses.nodus)}${field('trade-reserve-bsc','My BSC address',reserveAddresses.bsc)}</div>${board?`<p>${board.listings.length} ${T('unverified advertisements')}</p><div class="trade-board-list">${board.listings.map(listing=>`<section class="trade-leg"><h3>${esc(listing.name)}</h3><p>${esc(T(listing.side==='sell_nodus'?'Sell NODUS':'Buy NODUS'))} · ${esc(listing.nodusAmount)} NODUS ↔ ${esc(listing.usdtAmount)} TEST-USDT</p><p><code>${esc(listing.asset?.token)}</code></p><p>${T('Advertisement ID')}: <code>${esc(listing.id)}</code></p><p>${T('Maker')} · NODUS: <code>${esc(listing.maker?.nodus)}</code><br>BSC: <code>${esc(listing.maker?.bsc)}</code></p>${listing.reservation?`<p>${T('Reserved until')}: ${esc(new Date(listing.reservation.expiresAt*1000).toISOString())}</p><p>${T('Taker')} · NODUS: <code>${esc(listing.reservation.taker?.nodus)}</code><br>BSC: <code>${esc(listing.reservation.taker?.bsc)}</code></p>`:''}<div class="trade-buttons">${button('Reserve whole offer','reserve:'+listing.id,boardBusy||!!listing.reservation)}${capabilities.has(listing.id)?button('Export advertisement management file','cap:'+listing.id,boardBusy):''}${capabilities.has(listing.id)?button('Cancel advertisement','cancel:'+listing.id,boardBusy):''}${capabilities.has(listing.id)&&listing.reservation?button('Prepare fresh trade from reservation','draft:'+listing.id,boardBusy):''}</div></section>`).join('')}</div>`:`<p>${T('Refresh to read shared offers. No network request is made when this tab opens.')}</p>`}<p>${T('Keep the advertisement management file private. It controls this advertisement, not either wallet. Cancellation only removes an advertisement; chain locks still require settlement or refunds.')}</p></div>`;bindBoard();}
  async function boardAction(action){if(boardBusy)return;capture();boardBusy=true;const serial=boardGeneration,operation=++boardOperationVersion;try{
    if(action==='board-refresh'){const result=await json('/api/trade/board');if(serial!==boardGeneration)return;if(result.schema!=='nodus-trade/board-v1'||!Array.isArray(result.listings)||result.listings.length>500)throw Error('Invalid board response.');board={...result,listings:result.listings.map(validateListing)};boardMessage=T('Shared offers refreshed. Advertisements remain unverified.');}
    else if(action==='board-publish'){const source=context.offer||context.draft?.();if(!source)throw Error('Fill the new-offer form first.');const createdAt=now();const listing={schema:'nodus-trade/listing-v1',id:randomId(),name:source.name,side:source.side,nodusAmount:source.nodusAmount,usdtAmount:source.usdtAmount,maker:source.maker,asset:source.asset||{kind:'bep20',chainId:97,token:source.token,decimals:18,symbol:'TEST-USDT'},createdAt,expiresAt:createdAt+86400};const result=await json('/api/trade/listings',{method:'POST',body:JSON.stringify(listing)});if(!result.listing||!/^[0-9a-f]{64}$/.test(result.managementToken||''))throw Error('Invalid board response.');result.listing=validateListing(result.listing);capabilities.set(result.listing.id,result.managementToken);if(serial!==boardGeneration)return;board=board||{schema:'nodus-trade/board-v1',listings:[]};board.listings=[...board.listings.filter(item=>item.id!==result.listing.id),result.listing];boardMessage=T('Advertisement published. Export its private management file before closing.');}
    else{const [kind,id]=action.split(':');const listing=board?.listings.find(item=>item.id===id);if(!listing)throw Error('The advertisement is unavailable.');if(kind==='reserve'){const result=await json('/api/trade/reserve',{method:'POST',body:JSON.stringify({id,taker:{...reserveAddresses}})});if(serial!==boardGeneration)return;result.listing=validateListing({...result.listing,reservation:result.reservation||result.listing?.reservation});board.listings=board.listings.map(item=>item.id===id?result.listing:item);if(result.reservation)board.listings.find(item=>item.id===id).reservation=result.reservation;boardMessage=T('Reserved temporarily. Agree on fresh trade terms with the maker; no coins were locked.');}
      else if(kind==='cap'){download('PRIVATE-nodus-trade-advertisement-'+id.slice(2,14)+'.json',JSON.stringify({schema:'nodus-trade/listing-management-v1',id,managementToken:capabilities.get(id)},null,2)+'\n');boardMessage=T('Private management file downloaded.');}
      else if(kind==='cancel'){await json('/api/trade/cancel',{method:'POST',body:JSON.stringify({id,managementToken:capabilities.get(id)})});if(serial!==boardGeneration)return;board.listings=board.listings.filter(item=>item.id!==id);capabilities.delete(id);boardMessage=T('Advertisement removed. This does not cancel any chain transaction.');}
      else if(kind==='draft'){context.onDraft?.(listingFields(listing,listing.reservation.taker));boardMessage=T('Reservation copied to a draft. Review addresses and create a fresh offer with a new secret.');}
    }
  }catch(e){if(serial===boardGeneration&&e.name!=='AbortError')boardMessage=statusError(e);}finally{if(operation===boardOperationVersion){boardBusy=false;if(target&&mode==='board')renderBoard();}}}
  function bindBoard(){target.querySelectorAll('[data-live-action]').forEach(el=>el.onclick=()=>boardAction(el.dataset.liveAction));const upload=target.querySelector('#trade-board-management-import');if(upload)upload.onchange=async event=>{const file=event.target.files?.[0];if(!file)return;const serial=boardGeneration;try{if(file.size>4096)throw Error('The file is too large.');const cap=JSON.parse(await file.text());if(serial!==boardGeneration)return;if(cap.schema!=='nodus-trade/listing-management-v1'||!tokenPattern.test(cap.id)||!/^[0-9a-f]{64}$/.test(cap.managementToken)||Object.keys(cap).some(key=>!['schema','id','managementToken'].includes(key)))throw Error('Invalid management file.');capabilities.set(cap.id,cap.managementToken);boardMessage=T('Management capability loaded in this session only. Refresh shared offers.');}catch(e){boardMessage=statusError(e);}renderBoard();};}
  globalThis.addEventListener?.('nodus-trade-wallet-change',()=>{if(mode!=='network')return;capture();invalidate();message=T('Wallet account or network changed. Refresh both networks and prepare a new request.');renderNetwork();});
  globalThis.addEventListener?.('hashchange',()=>{if(globalThis.location?.hash!=='#trade')globalThis.NodusTradeLive?.unmount();});
  globalThis.NodusTradeLive=Object.freeze({
    mount(element,options){capture();const previous=currentOfferId;currentOfferId=options.offer?.id;invalidate();++boardGeneration;++boardOperationVersion;++operationVersion;busy=false;boardBusy=false;target=element;context=options;mode=options.mode;if(previous!==options.offer?.id){session=null;addresses={nodus:'',bsc:''};secretInput='';message='';}if(mode==='board')renderBoard();else renderNetwork();},
    unmount(){capture();invalidate();++boardGeneration;++boardOperationVersion;++operationVersion;target=null;context=null;mode='';secretInput='';},
    getState(){return {session:session&&C().copy(session),observations:observations&&C().copy(observations),inspection:inspection&&C().copy(inspection),requestPrepared:!!pending,board:board&&C().copy(board)};}
  });
})();
